      "rationale": "These spans supply the recurrence criterion, unresolved cases, consequences of a potentially reversed ranking, and limits of the selection rule."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C057.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
